+static MYSQL *loss_open_test_database(void)
+{
+  const char *port_text;
+  MYSQL *connection;
+
+  connection = mysql_init(NULL);
+  if (connection == NULL)
+  {
+    return NULL;
+  }
+  port_text = getenv("LUMINARI_TEST_MYSQL_PORT");
+  if (mysql_real_connect(
+          connection, getenv("LUMINARI_TEST_MYSQL_HOST"), getenv("LUMINARI_TEST_MYSQL_USER"),
+          getenv("LUMINARI_TEST_MYSQL_PASSWORD"), getenv("LUMINARI_TEST_MYSQL_DATABASE"),
+          port_text != NULL ? (unsigned int)strtoul(port_text, NULL, 10) : 3306, NULL, 0) == NULL)
+  {
+    mysql_close(connection);
+    return NULL;
+  }
+  return connection;
+}
+
+/* Assert the one row of the last query on `connection`. */
+static void loss_assert_row(CuTest *tc, MYSQL *connection, const char *first, const char *second,
+                            const char *third)
+{
+  MYSQL_RES *result;
+  MYSQL_ROW row;
+
+  result = mysql_store_result(connection);
+  CuAssertPtrNotNull(tc, result);
+  row = mysql_fetch_row(result);
+  CuAssertPtrNotNull(tc, row);
+  CuAssertStrEquals(tc, first, row[0]);
+  CuAssertStrEquals(tc, second, row[1]);
+  CuAssertStrEquals(tc, third, row[2]);
+  mysql_free_result(result);
+}
